import {useState} from "react";
import "./BoardMain.css";

export const BoardMain = ()=>{

    const [searchKey, setSearchKey] = useState("");
    const [orderBy, setOrderBy] = useState("");

    const loadArticles = ()=>{
        fetch('/articles', {
            method: 'GET',
            headers: {
                "Content-Type": "application/json"
            },
            body: JSON.stringify({
                searchKey: searchKey,
                orderBy: orderBy
            })
        })
            .then(res=>res.json())
            .then(data=>{

            })
            .catch()
    }

    return <div>
        <h1 style={{display: "flex", justifyContent: "center", width: "100%"}}>BOARD</h1>
        <br/>

        <form id={"search-form"} style={{display:"flex", justifyContent:"center"}}>
            <input type={"text"} value={searchKey} onInput={(e)=>{
                setSearchKey(e.target.value);
            }}/>
            <button>Search</button>
        </form>
        <br/>

        <div id="menu-bar" style={{
            width: "80%",
            margin: "0 auto",
            display: "flex",
            justifyContent: "flex-end"
        }}>
            <button>+</button>&nbsp;
        </div>

        <table id="contents-list" className="board-table"
               style={{width: "80%", margin:"0 auto", justifyContent: "center"}}>
            <thead>
            <th style={{width: "5%"}}>No.</th>
            <th style={{width: "40%"}}>Title</th>
            <th style={{width: "22%"}}>Writer</th>
            <th style={{width: "25%"}}>Date</th>
            <th style={{width: "5%"}}>Views</th>
            </thead>
            <tbody>
            </tbody>
        </table>

    </div>;
}
